use std::path::PathBuf;
pub fn validate(executable:&str)->Result<PathBuf,String>{let path=PathBuf::from(executable);if !path.is_absolute()||path.extension().and_then(|x|x.to_str()).map(|x|!x.eq_ignore_ascii_case("exe")).unwrap_or(true){return Err("Selecione um caminho absoluto para um executável .exe".into())}let m=std::fs::symlink_metadata(&path).map_err(|e|e.to_string())?;if !m.is_file()||m.file_type().is_symlink(){return Err("Executável inválido".into())}let path=path.canonicalize().map_err(|e|e.to_string())?;let win=PathBuf::from(std::env::var_os("SystemRoot").ok_or("SystemRoot ausente")?).canonicalize().map_err(|e|e.to_string())?;if path.starts_with(win){return Err("Executáveis do Windows estão protegidos".into())}Ok(path)}
